def _load_aic_grouped_matmul_step4_worker_sequence_base_service(
        repository_root):
    """Load the immutable first step-4 GroupedMatmul sequence campaign."""

    path = repository_root / (
        _AIC_GROUPED_MATMUL_STEP4_WORKER_SEQUENCE_REFERENCE)
